window.BOOK={"key":"ibnashir","app":"mutoon-ibnashir","lsk":"mutoon_ibnashir_v1","prefix":"ib_","title":"متن ابن عاشر","sub":"الفقه المالكي مع العقيدة والتصوف: المرشد المعين على الضروري من علوم الدين · عبد الواحد بن عاشر (ت ١٠٤٠هـ) · ٣١٧ بيتًا","poems":[{"id":"ibnashir","title":"متن ابن عاشر","nazim":"أبو محمد عبد الواحد بن أحمد بن عاشر الأنصاري الأندلسي الفاسي","death":"ت ١٠٤٠هـ","meter":"الرجز","source":"وزارة الأوقاف والشؤون الإسلامية المغربية (habous.gov.ma): كتاب المرشد المعين على الضروري من علوم الدين لابن عاشر، من نسخة أرشيف الإنترنت","srcUrl":"https://web.archive.org/web/20190920052435/http://www.habous.gov.ma/%D8%AF%D9%84%D9%8A%D9%84-%D8%A7%D9%84%D8%B9%D8%A7%D9%84%D9%85-%D8%A7%D9%84%D9%85%D8%A4%D8%B7%D8%B1-%D9%81%D9%8A-%D9%85%D9%8A%D8%AB%D8%A7%D9%82-%D8%A7%D9%84%D8%B9%D9%84%D9%85%D8%A7%D8%A1/1166-%D9%83%D8%AA%D8%A7%D8%A8-%D8%A7%D9%84%D9%85%D8%B1%D8%B4%D8%AF-%D8%A7%D9%84%D9%85%D8%B9%D9%8A%D9%86-%D8%B9%D9%84%D9%89-%D8%A7%D9%84%D8%B6%D8%B1%D9%88%D8%B1%D9%8A-%D9%85%D9%86-%D8%B9%D9%84%D9%88%D9%85-%D8%A7%D9%84%D8%AF%D9%8A%D9%86-%D9%84%D8%A7%D8%A8%D9%86-%D8%B9%D8%A7%D8%B4%D8%B1/7113-%D9%85%D9%82%D8%AF%D9%85%D8%A9-%D9%85%D9%8E%D8%AA%D9%92%D9%86%D9%8F-%D8%A7%D9%84%D9%85%D9%8F%D8%B1%D9%92%D8%B4%D9%90%D8%AF%D9%90-%D8%A7%D9%84%D9%85%D9%8F%D8%B9%D9%90%D9%8A%D9%86%D9%90-%D9%84%D8%A7%D8%A8%D9%92%D9%86%D9%90-%D8%B9%D9%8E%D8%A7%D8%B4%D9%90%D8%B1%D9%8D.html","note":"النص المشكول من نشرة وزارة الأوقاف المغربية للمتن، وقوبل كلمةً كلمةً بسكربت على الأبيات في «الدر الثمين» لميارة (المكتبة الشاملة) وعلى نسخة مفردة ثانية. صُحّحت أخطاء الطباعة، ورُدّت كلمة «فصل» إلى أوائل الأبيات التي يقتضيها الوزن، وكل ذلك في تقرير المصادر. عدد الأبيات ٣١٧، والناظم يذكر في الخاتمة أنها ٣١٤.","verses":[["يَقُولُ عَبْدُ الوَاحِدِ بْنُ عَاشِرِ","مُبْتَدِئًا بِاسْمِ الإِلَهِ الْقَادِرِ"],["الْحَمْدُ لِلَّهِ الَّذِي عَلَّمَنَا","مِنَ الْعُلُومِ مَا بِهِ كَلَّفَنَا"],["صَلَّى وَسَلَّمَ عَلَى مُحَمَّدِ","وَآلِهِ وَصَحْبِهِ وَالْمُقْتَدِي"],["وَبَعْدُ فَالْعَوْنُ مِنَ اللهِ الْمَجِيدْ","فِي نَظْمِ أَبْيَاتٍ لِلْأُمِّيِّ تُفِيدْ"],["فِي عَقْدِ الأَشْعَرِي وَفِقْهِ مَالِكِ","وَفِي طَرِيقَةِ الْجُنَيْدِ السَّالِكِ"],["وَحُكْمُنَا العَقْلِي قَضِيَّةٌ بِلَا","وَقْفٍ عَلَى عَادَةٍ أَوْ وَضْعٍ جَلَا"],["أَقْسَامُ مُقْتَضَاهُ بِالْحَصْرِ تُمَازْ","وَهْيَ الْوُجُوبُ الاِسْتِحَالَةُ الْجَوَازْ"],["فَوَاجِبٌ لَا يَقْبَلُ النَّفْيَ بِحَالْ","وَمَا أَبَى الثُّبُوتَ عَقْلاً الْمُحَالْ"],["وَجَائِزًا مَا قَابَلَ الأَمْرَيْنِ سِمْ","لِلضَّرُورِي وَالنَّظَرِي كُلٌّ قُسِمْ"],["أَوَّلُ وَاجِبٍ عَلَى مَنْ كُلِّفَا","مُمَكَّنًا مِنْ نَظَرٍ أَنْ يَعْرِفَا"],["اللهَ وَالرُّسُلَ بِالصِّفَاتِ","مِمَّا عَلَيْهَا نَصَبَ الآيَاتِ"],["وَكُلُّ تَكْلِيفٍ بِشَرْطِ الْعَقْلِ","مَعَ الْبُلُوغِ بِدَمٍ أَوْ حَمْلِ"],["أَوْ بِمَنِيٍّ أَوْ بِإِنْبَاتِ الشَّعَرْ","أَوْ بِثَمَانِ عَشْرَةٍ حَوْلاً ظَهَرْ"],["يَجِبُ لِلَّهِ الْوُجُودُ وَالْقِدَمْ","كَذَا الْبَقَاءُ وَالْغِنَى الْمُطْلَقُ عَمّْ"],["وَخُلْفُهُ لِخَلْقِهِ بِلَا مِثَالْ","وَوَحْدَةُ الذَّاتِ وَوَصْفٍ وَالْفِعَالْ"],["وَقُدْرَةٌ إِرَادَةٌ عِلْمٌ حَيَاةْ","سَمْعٌ كَلَامٌ بَصَرٌ ذِي وَاجِبَاتْ"],["وَيَسْتَحِيلُ ضِدُّ هَذِهِ الصِّفَاتْ","الْعَدَمُ الْحُدُوثُ ذَا لِلْحَادِثَاتْ"],["كَذَا الْفَنَا وَالاِفْتِقَارُ عُدَّهْ","وَأَنْ يُمَاثَلَ وَنَفْيُ الْوَحْدَةْ"],["عَجْزٌ كَرَاهَةٌ وَجَهْلٌ وَمَمَاتْ","وَصَمَمٌ وَبَكَمٌ عَمًى صُمَاتْ"],["يَجُوزُ فِي حَقِّهِ فِعْلُ الْمُمْكِنَاتْ","بِأَسْرِهَا وَتَرْكُهَا فِي الْعَدَمَاتْ"],["وُجُودُهُ لَهُ دَلِيلٌ قَاطِعْ","حَاجَةُ كُلِّ مُحْدَثٍ لِلصَّانِعْ"],["لَوْ حَدَثَتْ بِنَفْسِهَا الأَكْوَانُ","لَاجْتَمَعَ التَّسَاوِي وَالرُّجْحَانُ"],["وَذَا مُحَالٌ وَحُدُوثُ الْعَالَمِ","مِنْ حَدَثِ الأَعْرَاضِ مَعْ تَلَازُمِ"],["لَوْ لَمْ يَكُ الْقِدَمُ وَصْفَهُ لَزِمْ","حُدُوثُهُ دَوْرٌ تَسَلْسُلٌ حُتِمْ"],["لَوْ أَمْكَنَ الْفَنَاءُ لَانْتَفَى الْقِدَمْ","لَوْ مَاثَلَ الْخَلْقَ حُدُوثُهُ انْحَتَمْ"],["لَوْ لَمْ يَجِبْ وَصْفُ الْغِنَى لَهُ افْتَقَرْ","لَوْ لَمْ يَكُنْ بِوَاحِدٍ لَمَا قَدَرْ"],["لَوْ لَمْ يَكُنْ حَيًّا مُرِيدًا عَالِمَا","وَقَادِرًا لَمَا رَأَيْتَ عَالَمَا"],["وَالتَّالِ فِي السِّتِّ الْقَضَايَا بَاطِلُ","قَطْعًا مُقَدَّمٌ إِذًا مُمَاثِلُ"],["وَالسَّمْعُ وَالْبَصَرُ وَالكَلَامُ","بِالنَّقْلِ مَعْ كَمَالِهِ تُرَامُ"],["لَوِ اسْتَحَالَ مُمْكِنٌ أَوْ وَجَبَا","قَلْبَ الْحَقَائِقِ لُزُومًا أَوْجَبَا"],["يَجِبُ لِلرُّسْلِ الْكِرَامِ الصِّدْقُ","أَمَانَةٌ تَبْلِيغُهُمْ يَحِقُّ"],["مُحَالٌ الْكَذِبُ وَالْمَنْهِيُّ","كَعَدَمِ التَّبْلِيغِ يَا ذَكِيُّ"],["يَجُوزُ فِي حَقِّهِمُ كُلُّ عَرَضْ","لَيْسَ مُؤَدِّيًا لِنَقْصٍ كَالْمَرَضْ"],["لَوْ لَمْ يَكُونُوا صَادِقِينَ لَلَزِمْ","أَنْ يَكْذِبَ الإِلَهُ فِي تَصْدِيقِهِمْ"],["إِذْ مُعْجِزَاتُهُمْ كَقَوْلِهِ وَبَرّْ","صَدَقَ هَذَا الْعَبْدُ فِي كُلِّ خَبَرْ"],["لَوِ انْتَفَى التَّبْلِيغُ أَوْ خَانُوا حُتِمْ","أَنْ يُقْلَبَ الْمَنْهِيُّ طَاعَةً لَهُمْ"],["جَوَازُ الأَعْرَاضِ عَلَيْهِمْ حُجَّتُهْ","وُقُوعُهَا بِهِمْ تَسَلٍّ حِكْمَتُهْ"],["وَقَوْلُ لَا إِلَهَ إِلَّا اللهُ","مُحَمَّدٌ أَرْسَلَهُ الإِلَهُ"],["يَجْمَعُ كُلَّ هَذِهِ الْمَعَانِي","كَانَتْ لِذَا عَلَامَةَ الإِيمَانِ"],["وَهِيَ أَفْضَلُ وُجُوهِ الذِّكْرِ","فَاشْغَلْ بِهَا الْعُمْرَ تَفُزْ بِالذُّخْرِ"],["فَصْلٌ وَطَاعَةُ الْجَوَارِحِ الْجَمِيعْ","قَوْلاً وَفِعْلاً هُوَ الاِسْلَامُ الرَّفِيعْ"],["قَوَاعِدُ الإِسْلَامِ خَمْسٌ وَاجِبَاتْ","وَهْيَ الشَّهَادَتَانِ شَرْطُ الْبَاقِيَاتْ"],["ثُمَّ الصَّلَاةُ وَالزَّكَاةُ فِي الْقِطَاعْ","وَالصَّوْمُ وَالْحَجُّ عَلَى مَنِ اسْتَطَاعْ"],["الاِيمَانُ جَزْمٌ بِالإِلَهِ وَالْكُتُبْ","وَالرُّسْلِ وَالأَمْلَاكِ مَعْ بَعْثٍ قَرُبْ"],["وَقَدَرٍ كَذَا صِرَاطٌ مِيزَانْ","حَوْضُ النَّبِيِّ جَنَّةٌ وَنِيرَانْ"],["وَأَمَّا الاِحْسَانُ فَقَالَ مَنْ دَرَاهْ","أَنْ تَعْبُدَ اللهَ كَأَنَّكَ تَرَاهْ"],["إِنْ لَمْ تَكُنْ تَرَاهُ إِنَّهُ يَرَاكْ","وَالدِّينُ ذِي الثَّلَاثُ خُذْ أَقْوَى عُرَاكْ"],["الْحُكْمُ فِي الشَّرْعِ خِطَابُ رَبِّنَا","الْمُقْتَضِي فِعْلَ الْمُكَلَّفِ افْطُنَا"],["بِطَلَبٍ أَوْ إِذْنٍ أَوْبِوَضْعِ","لِسَبَبٍ أَوْ شَرْطٍ أَوْ ذِي مَنْعِ"],["أَقْسَامُ حُكْمِ الشَّرْعِ خَمْسَةٌ تُرَامْ","فَرْضٌ وَنَدْبٌ وَكَرَاهَةٌ حَرَامْ"],["ثُمَّ إِبَاحَةٌ فَمَأْمُورٌ جُزِمْ","فَرْضٌ وَدُونَ الْجَزْمِ مَنْدُوبٌ وُسِمْ"],["ذُو النَّهْيِ مَكْرُوهٌ وَمَعْ حَتْمٍ حَرَامْ","مَأْذُونُ وَجْهَيْهِ مُبَاحٌ ذَا تَمَامْ"],["وَالْفَرْضُ قِسْمَانِ كِفَايَةٌ وَعَيْنْ","وَيَشْمَلُ الْمَنْدُوبُ سُنَّةً بِذَيْنْ"],["فَصْلٌ وَتَحْصُلُ الطَّهَارَةُ بِمَا","مِنَ التَّغَيُّرِ بِشَيْءٍ سَلِمَا"],["إِذَا تَغَيَّرَ بِنَجْسٍ طُرِحَا","أَوْ طَاهِرٍ لِعَادَةٍ قَدْ صَلُحَا"],["إِلَّا إِذَا لَازَمَهُ فِي الْغَالِبِ","كَمُغْرَةٍ فَمُطْلَقٌ كَالذَّائِبِ"],["فَرَائِضُ الْوُضُوءِ سَبْعَةٌ وَهِي","دَلْكٌ وَفَوْرٌ نِيَّةٌ فِي بَدْئِهِ"],["وَلْيَنْوِ رَفْعَ حَدَثٍ أَوْ مُفْتَرَضْ","أَوِ اسْتِبَاحَةً لِمَمْنُوعٍ عَرَضْ"],["وَغَسْلُ وَجْهٍ غَسْلُهُ الْيَدَيْنِ","وَمَسْحُ رَأْسٍ غَسْلُهُ الرِّجْلَيْنِ"],["وَالْفَرْضُ عَمَّ مَجْمَعَ الأُذْنَيْنِ","وَالْمَرْفِقَيْنِ عَمَّ وَالْكَعْبَيْنِ"],["خَلِّلْ أَصَابِعَ الْيَدَيْنِ وَشَعَرْ","وَجْهٍ إِذَا مِنْ تَحْتِهِ الْجِلْدُ ظَهَرْ"],["سُنَنُهُ السَّبْعُ ابْتِدَا غَسْلِ الْيَدَيْنْ","وَرَدُّ مَسْحِ الرَّأْسِ مَسْحُ الأُذُنَيْنْ"],["مَضْمَضَةُ اسْتِنْشَاقٌ اسْتِنْثَارُ","تَرْتِيبُ فَرْضِهِ وَذَا الْمُخْتَارُ"],["وَأَحَدَ عْشَرَ الْفَضَائِلُ أَتَتْ","تَسْمِيَةٌ وَبُقْعَةٌ قَدْ طَهُرَتْ"],["تَقْلِيلُ مَاءٍ وَتَيَامُنُ الإِنَا","وَالشَّفْعُ وَالتَّثْلِيثُ فِي مَغْسُولِنَا"],["بَدْءُ الْمَيَامِنِ سِوَاكٌ وَنُدِبْ","تَرْتِيبُ مَسْنُونِهِ أَوْ مَعْ مَا يَجِبْ"],["وَبَدْأُ مَسْحِ الرَّأْسِ مِنْ مُقَدَّمِهْ","تَخْلِيلُهُ أَصَابِعًا بِقَدَمِهْ"],["وَكُرِهَ الزَّيْدُ عَلَى الْفَرْضِ لَدَى","مَسْحٍ وَفِي الْغَسْلِ عَلَى مَا حُدِّدَا"],["وَعَاجِزُ الْفَوْرِ بَنَى مَا لَمْ يَطُلْ","بِيُبْسِ الأَعْضَا فِي زَمَانٍ مُعْتَدِلْ"],["ذَاكِرُ فَرْضِهِ بِطُولٍ يَفْعَلُهْ","فَقَطْ وَفِي الْقُرْبِ الْمُوَالِي يُكْمِلُهْ"],["إِنْ كَانَ صَلَّى بَطَلَتْ وَمَنْ ذَكَرْ","سُنَّتُهُ يَفْعَلُهَا لِمَا حَضَرْ"],["فَصْلٌ نَوَاقِضُهُ سِتَّةَ عَشَرْ","بَوْلٌ وَرِيحٌ سَلَسٌ إِذَا نَدَرْ"],["وَغَائِطٌ نَوْمٌ ثَقِيلٌ مَذْيُ","سُكْرٌ وَإِغْمَاءٌ جُنُونٌ وَدْيُ"],["لَمْسٌ وَقُبْلَةُ وَذَا إِنْ وُجِدَتْ","لَذَّةُ عَادَةٍ كَذَا إِنْ قُصِدَتْ"],["إِلْطَافُ مَرْأَةٍ كَذَا مَسُّ الذَّكَرْ","وَالشَّكُّ فِي الْحَدَثِ كُفْرُ مَنْ كَفَرْ"],["وَيَجِبُ اسْتِبْرَاءُ الاَخْبَثَيْنِ مَعْ","سَلْتِ وَنَتْرٍ ذَكَرٍ وَالشَّدَّ دَعْ"],["وَجَازَ الاِسْتِجْمَارُ مِنْ بَوْلِ ذَكَرْ","كَغَائِطٍ لَا مَا كَثِيرًا انْتَشَرْ"],["فَصْلٌ فُرُوضُ الْغُسْلِ قَصْدٌ يُحْتَضَرْ","فَوْرٌ عُمُومُ الدَّلْكِ تَخْلِيلُ الشَّعَرْ"],["فَتَابِعِ الْخَفِيَّ مِثْلَ الرُّكْبَتَيْنْ","وَالإِبْطِ وَالرُّفْغِ وَبَيْنَ الأَلْيَتَيْنْ"],["وَصِلْ لِمَا عَسُرَ بِالمِنْدِيلِ","وَنَحْوِهِ كَالْحَبْلِ وَالتَّوْكِيلِ"],["سُنَنُهُ مَضْمَضَةٌ غَسْلُ الْيَدَيْنْ","بَدْءًا وَالاِسْتِنْشَاقُ ثُقْبُ الأُذُنَيْنْ"],["مَنْدُوبُهُ الْبَدْءُ بِغَسْلِهِ الأَذَى","تَسْمِيَةٌ تَثْلِيثُ رَأْسِهِ كَذَا"],["تَقْدِيمُ أَعْضَاءِ الْوُضُو قِلَّةُ مَا","بَدْءٌ بِأَعْلَى وَيَمِينٍ خُذْهُمَا"],["تَبْدَأُ فِي الْغَسْلِ بِفَرْجٍ ثُمَّ كُفْ","عَنْ مَسِّهِ بِبَطْنِ أَوْ جَنْبِ الأَكُفّْ"],["أَوْ إِصْبَعٍ ثُمَّ إِذَا مَسَسْتَهْ","أَعِدْ مِنَ الْوُضُوءِ مَا فَعَلْتَهْ"],["مُوجِبُهُ حَيْضٌ نِفَاسٌ انْزَالْ","مَغِيبُ كَمْرَةٍ بِفَرْجٍ اسْجَالْ"],["وَالأَوَّلَانِ مَنَعَا الْوَطْءَ إِلَى","غُسْلٍ وَالاَخِرَانِ قُرْآنًا حَلَا"],["وَالْكُلُّ مَسْجِدًا وَسَهْوُ الاِغْتِسَالْ","مِثْلُ وُضُوئِكَ وَلَمْ تُعِدْ مُوَالْ"],["فَصْلٌ لِخَوْفِ ضُرٍّ أَوْ عَدَمِ مَا","عَوِّضْ مِنَ الطَّهَارَةِ التَّيَمُّمَا"],["وَصَلِّ فَرْضًا وَاحِدًا وَإِنْ تَصِلْ","جَنَازَةً وَسُنَّةً بِهِ يَحِلّْ"],["وَجَازَ لِلنَّفْلِ ابْتِدَا وَيَسْتَبِيحْ","الْفَرْضَ لَا الْجُمْعَةَ حَاضِرٌ صَحِيحْ"],["فُرُوضُهُ مَسْحُكَ وَجْهًا وَالْيَدَيْنْ","لِلْكُوعِ وَالنِّيَّةُ أُولَى الضَّرْبَتَيْنْ"],["ثُمَّ الْمُوَالَاةُ صَعِيدٌ طَهُرَا","وَوَصْلُهَا بِهِ وَوَقْتٌ حَضَرَا"],["آخِرُهُ لِلرَّاجِ آيِسٌ فَقَطْ","أَوَّلُهُ وَالْمُتَرَدِّدُ الْوَسَطْ"],["سُنَنُهُ مَسْحُهُمَا لِلْمِرْفَقِ","وَضَرْبَةُ الْيَدَيْنِ تَرْتِيبٌ بَقِي"],["مَنْدُوبُهُ تَسْمِيَةٌ وَصْفٌ حَمِيدْ","نَاقِضُهُ مِثْلُ الْوُضُوءِ وَيَزِيدْ"],["وُجُودُ مَاءٍ قَبْلَ أَنْ صَلَّى وَإِنْ","بَعْدُ يَجِدْ يُعِدْ بِوَقْتٍ إٍنْ يَكُنْ"],["كَخَائِفِ اللِّصِّ وَرَاجٍ قَدَّمَا","وَزَمَنٍ مُنَاوِلاً قَدْ عَدِمَا"],["فَرَائِضُ الصَّلَاةِ سِتَّ عَشَرَةْ","شُرُوطُهَا أَرْبَعَةٌ مُفْتَقِرَةْ"],["تَكْبِيرَةُ الإِحْرَامِ وَالْقِيَامُ","لَهَا وَنِيَّةٌ بِهَا تُرَامُ"],["فَاتِحَةٌ مَعَ الْقِيَامِ وَالرُّكُوعْ","وَالرَّفْعُ مِنْهُ وَالسُّجُودُ بِالخُضُوعْ"],["وَالرَّفْعُ مِنْهُ وَالسَّلَامُ وَالْجُلُوسْ","لَهُ وَتَرْتِيبُ أَدَاءٍ فِي الأُسُوسْ"],["وَالاِعْتِدَالُ مُطْمَئِنًّا بِالْتِزَامْ","تَابَعَ مَأْمُومٌ بِإِحْرَامٍ سَلَامْ"],["نِيَّتُهُ اقْتِدَا كَذَا الإِمَامُ فِي","خَوْفٍ وَجَمْعٍ جُمْعَةٍ مُسْتَخْلِفِ"],["شَرْطُهَا الاِسْتِقْبَالُ طُهْرُ الْخَبَثِ","وَسَتْرُ عَوْرَةٍ وَطُهْرُ الْحَدَثِ"],["بِالذِّكْرِ وَالْقُدْرَةِ فِي غَيْرِ الأَخِيرْ","تَفْرِيعُ نَاسِيهَا وَعَاجِزٌ كَثِيرْ"],["نَدْبًا يُعِيدَانِ بِوَقْتٍ كَالخَطَا","فِي قِبْلَةٍ لَا عَجْزِهَا أَوِ الْغِطَا"],["وَمَا عَدَا وَجْهَ وَكَفَّ الْحُرَّةِ","يَجِبُ سَتْرُهُ كَمَا فِي الْعَوْرَةِ"],["لَكِنْ لَدَى كَشْفٍ لِصَدْرٍ أَوْ شَعَرْ","أَوْ طَرَفٍ تُعِيدُ فِي الْوَقْتِ الْمُقَرّْ"],["شَرْطُ وُجُوبِهَا النَّقَا مِنَ الدَّمِ","بِقَصَّةٍ أَوِ الْجُفُوفِ فَاعْلَمِ"],["فَلَا قَضَى أَيَّامَهُ ثُمَّ دُخُولْ","وَقْتٍ فَأَدِّهَا بِهِ حَتْمًا أَقُولْ"],["سُنَنُهَا السُّورَةُ بَعْدَ الْوَاقِيَةْ","مَعَ الْقِيَامِ أَوَّلاً وَالثَّانِيَةْ"],["جَهْرٌ وَسِرٌّ بِمَحَلٍّ لَهُمَا","تَكْبِيرُهُ إِلَّا الَّذِي تَقَدَّمَا"],["كُلُّ تَشَهُّدٍ جُلُوسٌ أَوَّلُ","وَالثَّانِي لَا مَا لِلسَّلَامِ يَحْصُلُ"],["وَسَمِعَ اللهُ لِمَنْ حَمِدَهُ","فِي الرَّفْعِ مِنْ رُكُوعِهِ أَوْرَدَهُ"],["الْفَذُّ وَالإِمَامُ هَذَا أَكِّدَا","وَالْبَاقِ كَالْمَنْدُوبِ فِي الْحُكْمِ بَدَا"],["إِقَامَةٌ سُجُودُهُ عَلَى الْيَدَيْنْ","وَطَرَفِ الرِّجْلَيْنِ مِثْلُ الرُّكْبَتَيْنْ"],["إِنْصَاتُ مُقْتَدٍ بِجَهْرٍ ثُمَّ رَدّْ","عَلَى الإِمَامِ وَالْيَسَارِ وَأَحَدْ"],["بِهِ وَزَائِدُ سُكُونٍ لِلْحُضُورْ","سُتْرَةُ غَيْرِ مُقْتَدٍ خَافَ الْمُرُورْ"],["جَهْرُ السَّلَامِ كَلِمُ التَّشَهُّدِ","وَأَنْ يُصَلِّيَّ عَلَى مُحَمَّدِ"],["سُنَّ الأَذَانُ لِجَمَاعَةٍ أَتَتْ","فَرْضًا بِوَقْتِهِ وَغَيْرًا طَلَبَتْ"],["وَقَصْرُ مَنْ سَافَرَ أَرْبَعَ بُرُدْ","ظُهْرًا عِشًا عَصْرًا إِلَى حِينَ يَعُدْ"],["مِمَّا وَرَا السُّكْنَى إِلَيْهِ إِنْ قَدِمْ","مُقِيمُ أَرْبَعَةِ أَيَّامٍ يُتِمّْ"],["مَنْدُوبُهَا تَيَامُنٌ مَعَ السَّلَامْ","تَأْمِينُ مَنْ صَلَّى عَدَا جَهْرَ الإِمَامْ"],["وَقَوْلُ رَبَّنَا لَكَ الْحَمْدُ عَدَا","مَنْ أَمَّ وَالْقُنُوتُ فِي الصُّبْحِ بَدَا"],["رِدًا وَتَسْبِيحُ السُّجُودِ وَالرُّكُوعْ","سَدْلُ يَدٍ تَكْبِيرُهُ مَعَ الشُّرُوعْ"],["وَبَعْدَ أَنْ يَقُومَ مِنْ وُسْطَاهُ","وَعَقْدُهُ الثَّلَاثَ مِنْ يُمْنَاهُ"],["لَدَى التَّشَهُّدِ وَبَسْطُ مَا خَلَاهْ","تَحْرِيكُ سَبَّابَتِهَا حِينَ تَلَاهْ"],["وَالْبَطْنَ مِنْ فَخْذٍ رِجَالٌ يُبْعِدُونْ","وَمِرْفَقًا مِنْ رُكْبَةٍ إِذْ يَسْجُدُونْ"],["وَصِفَةُ الْجُلُوسِ تَمْكِينُ الْيَدِ","مِنْ رُكْبَتَيْهِ فِي الرُّكُوعِ وَزِدِ"],["نَصْبَهُمَا قِرَاءَةُ الْمَأْمُومِ فِي","سِرِيَّةٍ وَضْعُ الْيَدَيْنِ فَاقْتَفِي"],["لَدَى السُّجُودِ حَذْوَ أُذْنٍ وَكَذَا","رَفْعُ الْيَدَيْنِ عِنْدَ الإِحْرَامِ خُذَا"],["تَطْوِيلُهُ صُبْحًا وَظُهْرًا سُورَتَيْنْ","تَوَسُّطُ الْعِشَا وَقَصْرُ الْبَاقِيَيْنْ"],["كَالسُّورَةِ الأُخْرَى كَذَا الْوُسْطَى اسْتُحِبّْ","سَبْقُ يَدٍ وَضْعًا وَفِي الرَّفْعِ الرُّكَبْ"],["وَكَرِهُوا بَسْمَلَةً تَعَوُّذَا","فِي الْفَرْضِ وَالسُّجُودَ فِي الثَّوْبِ كَذَا"],["كَوْرُ عِمَامَةٍ وَبَعْضُ كُمِّهِ","وَحَمْلُ شَيْءٍ فِيهِ أَوْ فِي فَمِهِ"],["قِرَاءَةٌ لَدَى السُّجُودِ وَالرُّكُوعْ","تَفَكُّرُ الْقَلْبِ بِمَا نَافَى الْخُشُوعْ"],["وَعَبَثٌ وَالاِلْتِفَاتُ وَالدُّعَا","أَثْنَا قِرَاءَةٍ كَذَا إِنْ رَكَعَا"],["تَشْبِيكُ أَوْ فَرْقَعَةُ الأَصَابِعِ","تَخَصُّرٌ تَغْمِيضُ عَيْنٍ تَابِعِ"],["فَصْلٌ وَخَمْسُ صَلَوَاتٍ فَرْضُ عَيْنْ","وَهْيَ كِفَايَةٌ لِمَيْتٍ دُونَ مَيْنْ"],["فُرُوضُهَا التَّكْبِيرُ أَرْبَعًا دُعَا","وَنِيَّةٌ سَلَامُ سِرٍّ تَبِعَا"],["وَكَالصَّلَاةِ الْغُسْلُ دَفْنٌ وَكَفَنْ","وِتْرٌ كُسُوفٌ عِيدٌ اسْتِسْقَا سُنَنْ"],["فَجْرٌ رَغِيبَةٌ وَتُقْضَى لِلزَّوَالْ","وَالْفَرْضُ يُقْضَى أَبَدًا وَبِالتَّوَالْ"],["نُدِبَ نَفْلٌ مُطْلَقًا وَأُكِّدَتْ","تَحِيَّةٌ ضُحًى تَرَاوِيحٌ تَلَتْ"],["وَقَبْلَ وِتْرٍ مِثْلَ ظُهْرٍ عَصْرِ","وَبَعْدَ مَغْرِبٍ وَبَعْدَ ظُهْرٍ"],["فَصْلٌ لِنَقْصِ سُنَّةٍ سَهْوًا يُسَنّْ","قَبْلَ السَّلَامِ سَجْدَتَانِ أَوْ سُنَنْ"],["إِنْ أُكِّدَتْ وَمَنْ يَزِدْ سَهْوًا سَجَدْ","بَعْدُ كَذَا وَالنَّقْصَ غَلِّبْ إِنْ وَرَدْ"],["وَاسْتَدْرِكِ الْقَبْلِيَّ مَعْ قُرْبِ السَّلَامْ","وَاسْتَدْرِكِ الْبَعْدِيْ وَلَوْ مِنْ بَعْدِ عَامْ"],["عَنْ مُقْتَدٍ يَحْمِلُ هَذَيْنِ الإِمَامْ","وَبَطَلَتْ بِعَمْدِ نَفْخٍ أَوْ كَلَامْ"],["لِغَيْرِ إِصْلَاحٍ وَبِالْمُشْغِلِ عَنْ","فَرْضٍ وَفِي الْوَقْتِ أَعِدْ إِذَا يُسَنّْ"],["وَحَدَثٍ وَسَهْوِ زَيْدِ الْمِثْلِ","قَهْقَهَةٍ وَعَمْدِ شُرْبٍ أَكْلِ"],["وَسَجْدَةٍ قَيْءٍ وَذِكْرِ فَرْضِ","أَقَلَّ مِنْ سِتٍّ كَذِكْرِ الْبَعْضِ"],["وَفَوْتِ قَبْلِيٍّ ثَلَاثَ سُنَنْ","بِفَصْلِ مَسْجِدٍ كَطُولِ الزَّمَنْ"],["وَاسْتَدْرِكِ الرُّكْنَ فَإِنْ حَالَ رُكُوعْ","فَأَلْغِ ذَاتَ السَّهْوِ وَالْبِنَا يَطُوعْ"],["كَفِعْلِ مَنْ سَلَّمَ لَكِنْ يُحْرِمُ","لِلْبَاقِي وَالطُّولُ الْفَسَادَ مُلْزِمُ"],["مَنْ شَكَّ فِي رُكْنٍ بَنَى عَلَى الْيَقِينْ","وَلْيَسْجُدِ الْبَعْدِيَّ لَكِنْ قَدْ يَبِينْ"],["لِأَنْ بَنَوْا فِي فِعْلِهِمْ وَالْقَوْلِ","نَقْصٌ بِفَوْتِ سُورَةٍ فَالْقَبْلِي"],["كَذَاكِرِ الْوُسْطَى وَالاَيْدِي قَدْ رَفَعْ","وَرُكَبًا لَا قَبْلَ ذَا لَكِنْ رَجَعْ"],["فَصْلٌ بِمَوْطِنِ الْقُرَى قَدْ فُرِضَتْ","صَلَاةُ جُمْعَةٍ لِخُطْبَةٍ تَلَتْ"],["بِجَامِعٍ عَلَى مُقِيمٍ مَا انْعَذَرْ","حُرٍّ قَرِيبٍ بِكَفَرْسَخٍ ذَكَرْ"],["وَأَجْزَأَتْ غَيْرًا نَعَمْ قَدْ تُنْدَبُ","عِنْدَ النِّدَا السَّعْيُ إِلَيْهَا يَجِبُ"],["وَسُنَّ غُسْلٌ بِالرَّوَاحِ اتَّصَلَا","نُدِبَ تَهْجِيرٌ وَحَالٌ جَمُلَا"],["بِجُمْعَةٍ جَمَاعَةٌ قَدْ وَجَبَتْ","سُنَّتْ بِفَرْضٍ وَبِرَكْعَةٍ رَسَتْ"],["وَنُدِبَتْ إِعَادَةُ الْفَذِّ بِهَا","لَا مَغْرِبًا كَذَا عِشًا مُوتِرُهَا"],["شَرْطُ الإِمَامِ ذَكَرٌ مُكَلَّفُ","آتٍ بِالاَرْكَانِ وَحُكْمًا يَعْرِفُ"],["وَغَيْرُ ذِي فِسْقٍ وَلَحْنٍ وَاقْتِدَا","فِي جُمْعَةٍ حُرٌّ مُقِيمٌ عُدِّدَا"],["وَيُكْرَهُ السَّلَسُ وَالْقُرُوحُ مَعْ","بَادٍ لِغَيْرِهِمْ وَمَنْ يُكْرَهُ دَعْ"],["وَكَالأَشَلِّ وَإِمَامَةٌ بِلَا","رِدًا بِمَسْجِدٍ صَلَاةٌ تُجْتَلَى"],["بَيْنَ الأَسَاطِينِ وَقُدَّامَ الإِمَامْ","جَمَاعَةٌ بَعْدَ صَلَاةٍ ذِي الْتِزَامْ"],["وَرَاتِبٌ مَجْهُولٌ اوْ مَنْ أَبِنَا","وَأَغْلَفٌ عَبْدٌ خَصِيُّ ابْنُ زِنَا"],["وَجَازَ عِنِّينٌ وَأَعْمَى أَلْكَنُ","مُجَذَّمٌ خَفَّ وَهَذَا الْمُمْكِنُ"],["وَالْمُقْتَدِي الإِمَامَ يَتْبَعُ خَلَا","زِيَادَةٍ قَدْ حُقِّقَتْ عَنْهَا اعْدِلَا"],["وَأَحْرَمَ الْمَسْبُوقُ فَوْرًا وَدَخَلْ","مَعَ الإِمَامِ كَيْفَمَا كَانَ الْعَمَلْ"],["مُكَبِّرًا إِنْ سَاجِدًا أَوْ رَاكِعَا","أَلْفَاهُ لَا فِي جَلْسَةٍ وَتَابَعَا"],["إِنْ سَلَّمَ الإِمَامُ قَامَ قَاضِيَا","أَقْوَالَهُ وَفِي الْفِعَالِ بَانِيَا"],["كَبَّرَ إِنْ حَصَّلَ شَفْعًا أَوْ أَقَلّْ","مِنْ رَكْعَةٍ وَالسَّهْوَ إِذْ ذَاكَ احْتَمَلْ"],["وَيَسْجُدُ الْمَسْبُوقُ قَبْلِيَّ الإِمَامْ","مَعْهُ وَبَعْدِيًّا قَضَى بَعْدَ السَّلَامْ"],["أَدْرَكَ ذَاكَ السَّهْوَ أَوْ لَا قَيَّدُوا","مَنْ لَمْ يُحَصِّلْ رَكْعَةً لَا يَسْجُدُ"],["وَبَطَلَتْ لِمُقْتَدٍ بِمُبْطِلِ","عَلَى الإِمَامِ غَيْرَ فَرْعٍ مُنْجَلِي"],["مَنْ ذَكَرَ الْحَدَثَ أَوْ بِهِ غُلِبْ","إِنْ بَادَرَ الْخُرُوجَ مِنْهَا وَنُدِبْ"],["تَقْدِيمُ مُؤْتَمٍّ يُتِمُّ بِهِمُو","فَإِنْ أَبَاهُ انْفَرَدُوا أَوْ قَدَّمُوا"],["فُرِضَتِ الزَّكَاةُ فِيمَا يُرْتَسَمْ","عَيْنٍ وَحَبٍّ وَثِمَارٍ وَنَعَمْ"],["فِي الْعَيْنِ وَالأَنْعَامِ حَقَّتْ كُلَّ عَامْ","يَكْمُلُ وَالْحَبُّ بِالإِفْرَاكِ يُرَامْ"],["وَالتَّمْرُ وَالزَّبِيبُ بِالطِّيبِ وَفِي","ذِي الزَّيْتِ مِنْ زَيْتِهِ وَالْحَبُّ يَفِي"],["وَهِيَ فِي الثِّمَارِ وَالْحَبِّ الْعُشُرْ","أَوْ نِصْفُهُ إِنْ آلَةَ السَّقْيِ يَجُرّْ"],["خَمْسَةُ أَوْسُقٍ نِصَابٌ فِيهِمَا","فِي فِضَّةٍ قُلْ مِائَتَانِ دِرْهَمَا"],["عِشْرُونَ دِينَارًا نِصَابٌ فِي الذَّهَبْ","وَرُبُعُ الْعُشُرِ فِيهِمَا وَجَبْ"],["وَالْعَرْضُ ذُو التَّجْرِ وَدَيْنُ مَنْ أَدَارْ","قِيمَتُهَا كَالْعَيْنِ ثُمَّ ذُو احْتِكَارْ"],["زَكَّى لِقَبْضِ ثَمَنٍ أَوْ دَيْنٍ","عَيْنًا بِشَرْطِ الْحَوْلِ لِلْأَصْلَيْنِ"],["فِي كُلِّ خَمْسَةِ جِمَالٍ جَذَعَةْ","مِنْ غَنَمٍ بِنْتُ الْمَخَاضِ مُقْنِعَةْ"],["فِي الْخَمْسِ وَالْعِشْرِينَ وَابْنَةُ اللَّبُونْ","فِي سِتَّةٍ مَعَ الثَّلَاثِينَ تَكُونْ"],["سِتًّا وَأَرْبَعِينَ حِقَّةٌ كَفَتْ","جَذَعَةٌ إِحْدَى وَسِتِّينَ وَفَتْ"],["بِنْتَا لَبُونٍ سِتَّةً وَسَبْعِينْ","وَحِقَّتَانِ وَاحِدًا وَتِسْعِينْ"],["وَمَعْ ثَلَاثِينَ ثَلَاثٌ أَيْ بَنَاتْ","لَبُونٍ أَوْ خُذْ حِقَّتَيْنِ بِافْتِيَاتْ"],["إِذَا الثَّلَاثِينَ تَلَتْهَا الْمِائَةُ","فِي كُلِّ خَمْسِينَ كَمَالاً حِقَّةُ"],["وَكُلُّ أَرْبَعِينَ بِنْتٌ لِلَّبُونْ","وَهَكَذَا مَا زَادَ أَمْرُهُ يَهُونْ"],["عِجْلٌ تَبِيعٌ فِي ثَلَاثِينَ بَقَرْ","مُسِنَّةٌ فِي أَرْبَعِينَ تُسْتَطَرْ"],["وَهَكَذَا مَا ارْتَفَعَتْ ثُمَّ الْغَنَمْ","شَاةٌ لِأَرْبَعِينَ مَعْ أُخْرَى تُضَمّْ"],["فِي وَاحِدٍ عِشْرِينَ يَتْلُو وَمِئَةْ","وَمَعْ ثَمَانِينَ ثَلَاثٌ مُجْزِئَةْ"],["وَأَرْبَعًا خُذْ مِنْ مِئِينَ أَرْبَعِ","شَاةٌ لِكُلِّ مِائَةٍ إِنْ تُرْفَعِ"],["وَحَوْلُ الاَرْبَاحِ وَنَسْلٍ كَالأُصُولْ","وَالطَّارِ لَا عَمَّا يُزَكَّى أَنْ يَحُولْ"],["وَلَا يُزَكَّى وَقَصٌ مِنَ النَّعَمْ","كَذَاكَ مَا دُونَ النِّصَابِ وَلْيَعُمّْ"],["وَعَسَلٌ فَاكِهَةٌ مَعَ الْخُضَرْ","إِذْ هِيَ فِي الْمُقْتَاتِ مِمَّا يُدَّخَرْ"],["وَيَحْصُلُ النِّصَابُ مِنْ صِنْفَيْنِ","كَذَهَبٍ وَفِضَّةٍ مِنْ عَيْنِ"],["وَالضَّأْنُ لِلْمَعْزِ وَبُخْتٌ لِلْعِرَابْ","وَبَقَرٌ إِلَى الْجَوَامِيسِ اصْطِحَابْ"],["الْقَمْحُ لِلشَّعِيرِ لِلسُّلْتِ يُصَارْ","كَذَا الْقَطَانِي وَالزَّبِيبُ وَالثِّمَارْ"],["مَصْرِفُهَا الْفَقِيرُ وَالْمِسْكِينُ","غَازٍ وَعِتْقٌ عَامِلٌ مَدِينُ"],["مُؤَلَّفُ الْقَلْبِ وَمُحْتَاجٌ غَرِيبْ","أَحْرَارُ إِسْلَامٍ وَلَمْ يُقْبَلْ مُرِيبْ"],["فَصْلٌ زَكَاةُ الْفِطْرِ صَاعٌ وَتَجِبْ","عَنْ مُسْلِمٍ وَمَنْ بِرِزْقِهِ طُلِبْ"],["مِنْ مُسْلِمٍ بِجُلِّ عَيْشِ الْقَوْمِ","لِتُغْنِ حُرًّا مُسْلِمًا فِي الْيَوْمِ"],["صِيَامُ شَهْرِ رَمَضَانَ وَجَبَا","فِي رَجَبٍ شَعْبَانَ صَوْمٌ نُدِبَا"],["كَتِسْعِ حِجَّةٍ وَأَحْرَى الآخِرُ","كَذَا الْمُحَرَّمُ وَأَحْرَى الْعَاشِرُ"],["وَيَثْبُتُ الشَّهْرُ بِرُؤْيَةِ الْهِلَالْ","أَوْ بِثَلَاثِينَ قُبَيْلاً فِي كَمَالْ"],["فَرْضُ الصِّيَامِ نِيَّةٌ بِلَيْلِهِ","وَتَرْكُ وَطْءٍ شُرْبِهِ وَأَكْلِهِ"],["وَالْقَيْءِ مَعْ إِيصَالِ شَيْءٍ لِلْمَعِدْ","مِنْ أُذُنٍ أَوْ عَيْنٍ أَوْ أَنْفٍ وَرَدْ"],["وَقْتَ طُلُوعِ فَجْرِهِ إِلَى الْغُرُوبْ","وَالْعَقْلُ فِي أَوَّلِهِ شَرْطُ الْوُجُوبْ"],["وَلْيَقْضِ فَاقِدُهُ وَالْحَيْضُ مَنَعْ","صَوْمًا وَتَقْضِي الْفَرْضَ إِنْ بِهِ ارْتَفَعْ"],["وَيُكْرَهُ اللَّمْسُ وَفِكْرٌ سَلِمَا","دَأْبًا مِنَ الْمَذْيِ وَإِلَّا حَرُمَا"],["وَكَرِهُوا ذَوْقَ كَقِدْرٍ وَهَذَرْ","غَالِبُ قَيْءٍ وَذُبَابٍ مُغْتَفَرْ"],["غُبَارُ صَانِعٍ وَطُرْقٍ وَسِوَاكْ","يَابِسٌ اصْبَاحُ جَنَابَةٍ كَذَاكْ"],["وَنِيَّةٌ تَكْفِي لِمَا تَتَابَعُهْ","يَجِبُ إِلَّا إِنْ نَفَاهُ مَانِعُهْ"],["نُدِبَ تَعْجِيلٌ لِفِطْرٍ رَفَعَهْ","كَذَاكَ تَأْخِيرُ سُحُورٍ تَبِعَهْ"],["مَنْ أَفْطَرَ الْفَرْضَ قَضَاهُ وَلْيَزِدْ","كَفَّارَةً فِي رَمَضَانَ إِنْ عَمَدْ"],["لِأَكْلٍ أَوْ شُرْبِ فَمٍ أَوْ لِلْمَنِيّْ","وَلَوْ بِفِكْرٍ أَوْ لِرَفْضِ مَا بُنِيْ"],["بِلَا تَأَوُّلٍ قَرِيبٍ وَيُبَاحْ","لِلضُّرِّ أَوْ سَفَرِ قَصْرٍ أَيْ مُبَاحْ"],["وَعَمْدُهُ فِي النَّفْلِ دُونَ ضُرِّ","مُحَرَّمٌ وَلْيَقْضِ لَا فِي الْغَيْرِ"],["وَكَفِّرَنْ بِصَوْمِ شَهْرَيْنِ وِلَا","أَوْ عِتْقِ مَمْلُوكٍ بِالإِسْلَامِ حَلَا"],["وَفَضَّلُوا إِطْعَامَ سِتِّينَ فَقِيرْ","مُدًّا لِمِسْكِينٍ مِنَ الْعَيْشِ الْكَثِيرْ"],["الْحَجُّ فَرْضٌ مَرَّةً فِي الْعُمْرِ","أَرْكَانُهُ إِنْ تُرِكَتْ لَمْ تُجْبَرِ"],["الاِحْرَامُ وَالسَّعْيُ وُقُوفُ عَرَفَةْ","لَيْلَةَ الأَضْحَى وَالطَّوَافُ رَدِفَهْ"],["وَالْوَاجِبَاتُ غَيْرَ الاَرْكَانِ بِدَمْ","قَدْ جُبِرَتْ مِنْهَا طَوَافُ مَنْ قَدِمْ"],["وَوَصْلُهُ بِالسَّعْيِ مَشْيٌ فِيهِمَا","وَرَكْعَتَا الطَّوَافِ إِنْ تَحَتَّمَا"],["نُزُولُ مُزْدَلِفَ فِي رُجُوعِنَا","مَبِيتُ لَيْلَاتٍ ثَلَاثٍ بِمِنَى"],["إِحْرَامُ مِيقَاتٍ فَذُو الْحُلَيْفَةْ","لِطَيْبَ لِلشَّامِ وَمِصْرَ الْجُحْفَةْ"],["قَرْنٌ لِنَجْدٍ ذَاتُ عِرْقٍ لِلْعِرَاقْ","يَلَمْلَمُ الْيَمَنُ آتِيهَا وِفَاقْ"],["تَجَرُّدٌ مِنَ الْمَخِيطِ تَلْبِيَةْ","وَالْحَلْقُ مَعْ رَمْيِ الْجِمَارِ تَوْفِيَةْ"],["وَإِنْ تُرِدْ تَرْتِيبَ حَجِّكَ اسْمَعَا","بَيَانَهُ وَالذِّهْنَ مِنْكَ اسْتَجْمِعَا"],["إِنْ جِئْتَ رَابِغًا تَنَظَّفْ وَاغْتَسِلْ","كَوَاجِبٍ وَبِالشُّرُوعِ يَتَّصِلْ"],["وَالْبَسْ رِدًا وَأَزْرَةً نَعْلَيْنِ","وَاسْتَصْحِبِ الْهَدْيَ وَرَكْعَتَيْنِ"],["بِالكَافِرُونَ ثُمَّ الاِخْلَاصِ هُمَا","فَإِنْ رَكِبْتَ أَوْ مَشَيْتَ أَحْرِمَا"],["بِنِيَّةٍ تَصْحَبُ قَوْلاً أَوْ عَمَلْ","كَمَشْيٍ أَوْ تَلْبِيَةٍ مِمَّا اتَّصَلْ"],["وَجَدِّدَنْهَا كُلَّمَا تَجَدَّدَتْ","حَالٌ وَإِنْ صَلَّيْتَ ثُمَّ إِنْ دَنَتْ"],["مَكَّةُ فَاغْتَسِلْ بِذِي طُوًى بِلَا","دَلْكٍ وَمِنْ كَدَا الثَّنِيَّةِ ادْخُلَا"],["إِذَا وَصَلْتَ لِلْبُيُوتِ فَاتْرُكَا","تَلْبِيَةً وَكُلَّ شُغْلٍ وَاسْلُكَا"],["لِلْبَيْتِ مِنْ بَابِ السَّلَامِ وَاسْتَلِمْ","الْحَجَرَ الأَسْوَدَ كَبِّرْ وَأَتِمّْ"],["سَبْعَةَ أَشْوَاطٍ بِهِ وَقَدْ يَسَرْ","وَكَبِّرَنْ مُقَبِّلاً ذَاكَ الْحَجَرْ"],["مَتَى تُحَاذِيهِ كَذَا الْيَمَانِي","لَكِنَّ ذَا بِالْيَدِ خُذْ بَيَانِي"],["إِنْ لَمْ تَصِلْ لِلْحَجَرِ الْمَسْ بِالْيَدِ","وَضَعْ عَلَى الْفَمِ وَكَبِّرْ تَقْتَدِ"],["وَارْمُلْ ثَلَاثًا وَامْشِ بَعْدُ أَرْبَعًا","خَلْفَ الْمَقَامِ رَكْعَتَيْنِ أَوْقِعَا"],["وَادْعُ بِمَا شِئْتَ لَدَى الْمُلْتَزَمِ","وَالْحَجَرَ الأَسْوَدَ بَعْدُ اسْتَلِمِ"],["وَاخْرُجْ إِلَى الصَّفَا فَقِفْ مُسْتَقْبِلَا","عَلَيْهِ ثُمَّ كَبِّرَنْ وَهَلِّلَا"],["وَاسْعَ لِمَرْوَةٍ فَقِفْ مِثْلَ الصَّفَا","وَخُبَّ فِي بَطْنِ الْمَسِيلِ ذَا اقْتِفَا"],["أَرْبَعَ وَقْفَاتٍ بِكُلٍّ مِنْهُمَا","تَقِفُ وَالأَشْوَاطَ سَبْعًا تَمِّمَا"],["وَادْعُ بِمَا شِئْتَ بِسَعْيٍ وَطَوَافْ","وَبِالصَّفَا وَمَرْوَةٍ مَعَ اعْتِرَافْ"],["وَيَجِبُ الطُّهْرَانِ وَالسِّتْرُ عَلَى","مَنْ طَافَ نَدْبُهَا بِسَعْيٍ يُجْتَلَى"],["وَعُدْ فَلَبِّ لِمُصَلًّى عَرَفَةْ","وَخُطْبَةُ السَّابِعِ تَأْتِي لِلصِّفَةْ"],["وَثَامِنَ الشَّهْرِ اخْرُجَنَّ لِمِنَى","بِعَرَفَاتٍ تَاسِعًا نُزُولُنَا"],["وَاغْتَسِلَنْ قُرْبَ الزَّوَالِ وَاحْضُرَا","الْخُطْبَتَيْنِ وَاجْمَعَنَّ وَاقْصُرَا"],["ظُهْرَيْكَ ثُمَّ الْجَبَلَ اصْعَدْ رَاكِبَا","عَلَى وُضُوءٍ ثُمَّ كُنْ مُوَاظِبَا"],["عَلَى الدُّعَا مُهَلِّلاً مُبْتَهِلاً","مُصَلِّيًا عَلَى النَّبِيْ مُسْتَقْبِلَا"],["هُنَيْهَةً بَعْدَ غُرُوبِهَا تَقِفْ","وَانْفِرْ لِمُزْدَلِفَةٍ وَتَنْصَرِفْ"],["فِي الْمَأْزَمَيْنِ الْعَلَمَيْنِ نَكِّبِ","وَاقْصُرْ بِهَا وَاجْمَعْ عِشًا لِمَغْرِبِ"],["وَاحْطُطْ وَبِتْ بِهَا وَأَحْيِ لَيْلَتَكْ","وَصَلِّ صُبْحَكَ وَغَلِّسْ رِحْلَتَكْ"],["قِفْ وَادْعُ بِالْمَشْعَرِ لِلْإِسْفَارِ","وَأَسْرِعَنْ فِي بَطْنِ وَادِي النَّارِ"],["وَسِرْ كَمَا تَكُونُ لِلْعَقَبَةِ","فَارْمِ لَدَيْهَا بِحِجَارٍ سَبْعَةِ"],["مِنْ أَسْفَلٍ تُسَاقُ مِنْ مُزْدَلِفَةْ","كَالْفُولِ وَانْحَرْ هَدْيًا انْ بِعَرَفَةْ"],["أَوْقَفْتَهُ وَاحْلِقْ وَسِرْ لِلْبَيْتِ","فَطُفْ وَصَلِّ مِثْلَ ذَاكَ النَّعْتِ"],["وَارْجِعْ فَصَلِّ الظُّهْرَ فِي مِنًى وَبِتْ","إِثْرَ زَوَالِ غَدِهِ ارْمِ لَا تُفِتْ"],["ثَلَاثَ جَمْرَاتٍ بِسَبْعِ حَصَيَاتْ","لِكُلِّ جَمْرَةٍ وَقِفْ لِلدَّعَوَاتْ"],["طَوِيلاً اثْرَ الأَوَّلَيْنِ أَخِّرَا","عَقَبَةً وَكُلَّ رَمْيٍ كَبِّرَا"],["وَافْعَلْ كَذَاكَ ثَالِثَ النَّحْرِ وَزِدْ","إِنْ شِئْتَ رَابِعًا وَتَمَّ مَا قُصِدْ"],["وَمَنَعَ الإِحْرَامُ صَيْدَ الْبَرِّ","فِي قَتْلِهِ الْجَزَاءُ لَا كَالْفَأْرِ"],["وَعَقْرَبٍ مَعَ الْحِدَا كَلْبٍ عَقُورْ","وَحَيَّةٍ مَعَ الْغُرَابِ إِذْ يَجُورْ"],["وَمَنَعَ الْمُحِيطَ بِالْعُضْوِ وَلَوْ","بِنَسْجٍ أَوْ عَقْدٍ كَخَاتَمٍ حَكَوْا"],["وَالسَّتْرَ لِلْوَجْهِ أَوِ الرَّأْسِ بِمَا","يُعَدُّ سَاتِرًا وَلَكِنْ إِنَّمَا"],["تُمْنَعُ الأُنْثَى لُبْسَ قُفَّازٍ كَذَا","سَتْرٌ لِوَجْهٍ لَا لِسَتْرٍ أُخِذَا"],["وَمَنَعَ الطِّيبَ وَدُهْنًا وَضَرَرْ","قَمْلٍ وَإِلْقَا وَسَخٍ ظُفْرٍ شَعَرْ"],["وَيَفْتَدِي لِفِعْلِ بَعْضِ مَا ذُكِرْ","مِنَ الْمُحِيطِ لِهُنَا وَإِنْ عُذِرْ"],["وَمَنَعَ النِّسَا وَأَفْسَدَ الْجِمَاعْ","إِلَى الإِفَاضَةِ يُبَقَّى الاِمْتِنَاعْ"],["كَالصَّيْدِ ثُمَّ بَاقِي مَا قَدْ مُنِعَا","بِالْجَمْرَةِ الأَوْلَى يَحِلُّ فَاسْمَعَا"],["وَجَازَ الاِسْتِظْلَالُ بِالْمُرْتَفَعِ","لَا فِي الْمَحَامِلِ وَشُقْدُفٍ فَعِ"],["وُسُنَّةُ الْعُمْرَةِ فَافْعَلْهَا كَمَا","حَجٍّ وَفِي التَّنْعِيمِ نَدْبًا أَحْرِمَا"],["وَإِثْرَ سَعْيِكَ احْلِقَنْ وَقَصِّرَا","تَحِلَّ مِنْهَا وَالطَّوَافَ كَثِّرَا"],["مَا دُمْتَ فِي مَكَّةَ وَارْعَ الْحُرْمَةْ","لِجَانِبِ الْبَيْتِ وَزِدْ فِي الْخِدْمَةْ"],["وَلَازِمِ الصَّفَّ فَإِنْ عَزَمْتَ","عَلَى الْخُرُوجِ طُفْ كَمَا عَلِمْتَ"],["وَسِرْ لِقَبْرِ الْمُصْطَفَى بِأَدَبِ","وَنِيَّةٍ تُجَبْ لِكُلِّ مَطْلَبِ"],["سَلِّمْ عَلَيْهِ ثُمَّ زِدْ لِلصِّدِّيقْ","ثُمَّ إِلَى عُمَرَ نِلْتَ التَّوْفِيقْ"],["وَاعْلَمْ بِأَنَّ ذَا الْمَقَامَ يُسْتَجَابْ","فِيهِ الدُّعَا فَلَا تَمَلَّ مِنْ طِلَابْ"],["وَسَلْ شَفَاعَةً وَخَتْمًا حَسَنَا","وَعَجِّلِ الأَوْبَةَ إِذْ نِلْتَ الْمُنَى"],["وَادْخُلْ ضُحًى وَاصْحَبْ هَدِيَّةَ السُّرُورْ","إِلَى الأَقَارِبِ وَمَنْ بِكَ يَدُورْ"],["وَتَوْبَةٌ مِنْ كُلِّ ذَنْبٍ يُجْتَرَمْ","تَجِبُ فَوْرًا مُطْلَقًا وَهْيَ النَّدَمْ"],["بِشَرْطِ الاِقْلَاعِ وَنَفْيِ الإِصْرَارْ","وَلْيَتَلَافَ مُمْكِنًا ذَا اسْتِغْفَارْ"],["وَحَاصِلُ التَّقْوَى اجْتِنَابٌ وَامْتِثَالْ","فِي ظَاهِرٍ وَبَاطِنٍ بِذَا تُنَالْ"],["فَجَاءَتِ الأَقْسَامُ حَقًّا أَرْبَعَةْ","وَهِيَ لِلسَّالِكِ سُبْلُ الْمَنْفَعَةْ"],["يَغُضُّ عَيْنَيْهِ عَنِ الْمَحَارِمِ","يَكُفُّ سَمْعَهُ عَنِ الْمَآثِمِ"],["كَغِيبَةٍ نَمِيمَةٍ زُورٍ كَذِبْ","لِسَانُهُ أَحْرَى بِتَرْكِ مَا جُلِبْ"],["يَحْفَظُ بَطْنَهُ مِنَ الْحَرَامِ","يَتْرُكُ مَا شُبِّهَ بِاهْتِمَامِ"],["يَحْفَظُ فَرْجَهُ وَيَتَّقِي الشَّهِيدْ","فِي الْبَطْشِ وَالسَّعْيِ لِمَمْنُوعٍ يُرِيدْ"],["وَيُوقِفُ الأُمُورَ حَتَّى يَعْلَمَا","مَا اللهُ فِيهِنَّ بِهِ قَدْ حَكَمَا"],["يُطَهِّرُ الْقَلْبَ مِنَ الرِّيَاءِ","وَحَسَدٍ عُجْبٍ وَكُلِّ دَاءِ"],["وَاعْلَمْ بِأَنَّ أَصْلَ ذِي الآفَاتِ","حُبُّ الرِّيَاسَةِ وَطَرْحُ الآتِي"],["رَأْسُ الْخَطَايَا هُوَ حُبُّ الْعَاجِلَةْ","لَيْسَ الدَّوَا إِلَّا فِي الاِضْطِرَارِ لَهْ"],["يَصْحَبُ شَيْخًا عَارِفَ الْمَسَالِكْ","يَقِيهِ فِي طَرِيقِهِ الْمَهَالِكْ"],["يُذْكِرُهُ اللهَ إِذَا رَآهُ","وَيُوصِلُ الْعَبْدَ إِلَى مَوْلَاهُ"],["يُحَاسِبُ النَّفْسَ عَلَى الأَنْفَاسِ","وَيَزِنُ الْخَاطِرَ بِالْقِسْطَاسِ"],["وَيَحْفَظُ الْمَفْرُوضَ رَأْسَ الْمَالِ","وَالنَّفْلُ رِبْحُهُ بِهِ يُوَالِي"],["وَيُكْثِرُ الذِّكْرَ بِصَفْوِ لُبِّهِ","وَالْعَوْنُ فِي جَمِيعِ ذَا بِرَبِّهِ"],["يُجَاهِدُ النَّفْسَ لِرَبِّ الْعَالَمِينْ","وَيَتَحَلَّى بِمَقَامَاتِ الْيَقِينْ"],["خَوْفٌ رَجَا شُكْرٌ وَصَبْرٌ تَوْبَةْ","زُهْدٌ تَوَكُّلٌ رِضَا مَحَبَّةْ"],["يَصْدُقُ شَاهِدَهُ فِي الْمُعَامَلَةْ","يَرْضَى بِمَا قَدَّرَهُ الإِلَهُ لَهْ"],["يَصِيرُ عِنْدَ ذَاكَ عَارِفًا بِهِ","حُرًّا وَغَيْرُهُ خَلَا مِنْ قَلْبِهِ"],["فَحَبَّهُ الإِلَهُ وَاصْطَفَاهُ","لِحَضْرَةِ الْقُدُّوسِ وَاجْتَبَاهُ"],["ذَا الْقَدْرُ نَظْمًا لَا يَفِي بِالْغَايَةْ","وَفِي الَّذِي ذَكَرْتُهُ كِفَايَةْ"],["أَبْيَاتُهُ أَرْبَعَةَ عْشَرَ تَصِلْ","مَعَ ثَلَاثِمِئَةٍ عَدُّ الرُّسُلْ"],["سَمَّيْتُهُ بِالْمُرْشِدِ الْمُعِينِ","عَلَى الضَّرُورِي مِنْ عُلُومِ الدِّينِ"],["فَأَسْأَلُ النَّفْعَ بِهِ عَلَى الدَّوَامْ","مِنْ رَبِّنَا بِجَاهِ سَيِّدِ الأَنَامْ"],["قَدِ انْتَهَى وَالْحَمْدُ لِلَّهِ الْعَظِيمْ","صَلَّى وَسَلَّمَ عَلَى الْهَادِي الْكَرِيمْ"]],"secs":{"1":"مُقَدِّمَةُ الْمَتْنِ","6":"مُقَدِّمَةٌ لِكِتَابِ الاِعْتِقَادْ مُعِينَةٌ لِقَارِئِهَا عَلَى الْمُرَادْ","14":"كِتَابُ أُمِّ الْقَوَاعِدِ وَمَا انْطَوَتْ عَلَيْهِ مِنَ الْعَقَائِدِ","41":"فَصْلٌ فِي قَوَاعِدِ الإِسْلَامِ","48":"مُقَدِّمَةٌ مِنَ الأُصُولِ مُعِينَةٌ فِي فُرُوعِهَا عَلَى الْوُصُولِ","54":"كِتَابُ الطَّهَارَةِ","57":"فَصْلٌ فِي فَرَائِضِ الْوُضُوءِ","62":"فَصْلٌ فِي سُنَنِ الْوُضُوءِ","72":"فَصْلٌ فِي نَوَاقِضِ الْوُضُوءِ","78":"فَصْلٌ فِي فَرَائِضِ الْغُسْلِ","81":"سُنَنُ الْغُسْلِ","86":"مُوجِبُ الْغُسْلِ","89":"فَصْلٌ فِي التَّيَمُّمِ","92":"فُرُوضُ التَّيَمُّمِ","95":"سُنَنُ التَّيَمُّمِ","99":"كِتَابُ الصَّلَاةِ","112":"فَصْلٌ فِي سُنَنِ الصَّلَاةِ","124":"فَصْلٌ فِي مَنْدُوبَاتِ الصَّلَاةِ","140":"فَصْلٌ فِي فَرْضِ الْعَيْنِ وَفَرْضِ الْكِفَايَةِ","146":"فَصْلٌ فِي سُجُودِ السَّهْوِ","159":"فَصْلٌ فِي صَلَاةِ الْجُمُعَةِ","165":"فَصْلٌ فِي شُرُوطِ الإِمَامِ","182":"كِتَابُ الزَّكَاةِ","209":"فَصْلٌ فِي زَكَاةِ الْفِطْرِ","211":"كِتَابُ الصِّيَامِ","229":"كِتَابُ الْحَجِّ","291":"كِتَابُ مَبَادِئِ التَّصَوُّفِ وَهَوَادِي التَّعَرُّفْ","313":"الْخَاتِمَةُ"}}],"sharh":false};
